291	func TestUsePartialAndExceedsFailsWhole(t *testing.T) {
292		s := newStore(t)
293		if _, err := s.Reserve("c1", "r1", "part1", 5, expiryOK, nowOK); err != nil {
294			t.Fatalf("reserve: %v", err)
295		}
296		// 分批使用 2 + 3。
297		if _, err := s.Use("u1", "c1", 2, nowOK); err != nil {
298			t.Fatalf("use 2: %v", err)
299		}
300		if _, err := s.Use("u2", "c1", 3, nowOK); err != nil {
301			t.Fatalf("use 3: %v", err)
302		}
303		c, _ := s.Commitment("c1")
304		if c.Used != 5 || c.Unused() != 0 {
305			t.Fatalf("commitment after uses: used=%d unused=%d", c.Used, c.Unused())
306		}
307		st, _ := s.PartStatus("part1", nowOK)
308		if st.PhysicalRemaining != 5 {
309			t.Fatalf("physical remaining = %d, want 5", st.PhysicalRemaining)
310		}
311		// 已全部使用：新使用失败。
312		if _, err := s.Use("u3", "c1", 1, nowOK); !errors.Is(err, ErrCommitmentClosed) && !errors.Is(err, ErrUsageExceeded) {
313			t.Fatalf("use on fully-used: got %v", err)
314		}
315	
316		// 超未用数量：整次失败，不扣减。
317		if _, err := s.Reserve("c2", "r1", "part1", 3, expiryOK, nowOK); err != nil {
318			t.Fatalf("reserve c2: %v", err)
319		}
320		if _, err := s.Use("u4", "c2", 4, nowOK); !errors.Is(err, ErrUsageExceeded) {
321			t.Fatalf("over-use: got %v", err)
322		}
323		c2, _ := s.Commitment("c2")
324		if c2.Used != 0 {
325			t.Fatalf("failed use changed commitment: used=%d", c2.Used)
326		}
327		st2, _ := s.PartStatus("part1", nowOK)
328		if st2.PhysicalRemaining != 5 {
329			t.Fatalf("failed use changed stock: %d", st2.PhysicalRemaining)
330		}
331	}
