	"time"
)

// TestScratchUseConflictClassification 临时验证任务描述的全部场景。
func TestScratchUseConflictClassification(t *testing.T) {
	// 场景：库存 10、有效承诺 5、首次成功使用 2。
	s := newStore(t)
	first, err := s.Use("u1", "c1", 2, nowOK)
	if err != nil {
		t.Fatalf("first use: %v", err)
	}

	// 沿用编号，数量改为零或负数、承诺改为空串/不存在/已取消/到期/超量 → ErrConflict。
	cases := []struct {
		name     string
		commitID string
		quantity int
		now      time.Time
	}{
		{"zero quantity", "c1", 0, nowOK},
		{"negative quantity", "c1", -3, nowOK},
		{"empty commit id", "", 2, nowOK},
		{"unknown commitment", "cMissing", 2, nowOK},
		{"quantity over unused (4 > 3)", "c1", 4, nowOK},
	}
	for _, tc := range cases {
		if _, err := s.Use("u1", tc.commitID, tc.quantity, tc.now); !errors.Is(err, ErrConflict) {
			t.Fatalf("%s: got %v, want ErrConflict", tc.name, err)
		}
	}

	// 冲突提交后状态不变：实物 8、已用 2、有效占用 3。
	c, _ := s.Commitment("c1")
	if c.Used != 2 {
		t.Fatalf("used = %d, want 2", c.Used)
	}
	st, _ := s.PartStatus("part1", nowOK)
	if st.PhysicalRemaining != 8 || st.ActiveOccupied != 3 || st.Committable != 5 {
		t.Fatalf("state after conflicts: %+v", st)
	}

	// 新承诺取消后，用 u1 指向它仍是冲突（不按 closed，也不确认到期）。
	if _, err := s.Reserve("c2", "r1", "part1", 2, expiryOK, nowOK); err != nil {
		t.Fatalf("reserve c2: %v", err)
	}
	if _, err := s.Cancel("c2", nowOK); err != nil {
		t.Fatalf("cancel c2: %v", err)
	}
	if _, err := s.Use("u1", "c2", 2, nowOK); !errors.Is(err, ErrConflict) {
		t.Fatalf("conflict toward canceled commitment: got %v", err)
	}
	c2, _ := s.Commitment("c2")
	if c2.Used != 0 {
		t.Fatalf("conflict increased used on canceled commitment: %d", c2.Used)
	}

	// 新承诺到期时刻已过，用 u1 指向它仍是冲突，不借本次时刻确认到期。
	if _, err := s.Reserve("c3", "r1", "part1", 1, expiryOK, nowOK); err != nil {
		t.Fatalf("reserve c3: %v", err)
	}
	if _, err := s.Use("u1", "c3", 1, expiryOK); !errors.Is(err, ErrConflict) {
		t.Fatalf("conflict toward expiring commitment: got %v", err)
	}
	c3, _ := s.Commitment("c3")
	if c3.Expired {
		t.Fatalf("conflict confirmed expiry of new commitment")
	}

	// 原承诺随后到期/取消，原样重试取回首次记录，不再次扣库存。
	if _, err := s.Cancel("c1", nowOK); err != nil {
		t.Fatalf("cancel c1: %v", err)
	}
	got, err := s.Use("u1", "c1", 2, expiryOK.Add(30*day))
	if err != nil {
		t.Fatalf("idempotent retry after cancel+late now: %v", err)
	}
	if got != first {
		t.Fatalf("retry = %+v, want first %+v", got, first)
	}
	st2, _ := s.PartStatus("part1", nowOK)
	if st2.PhysicalRemaining != 8 {
		t.Fatalf("retry deducted stock: %d", st2.PhysicalRemaining)
	}

	// 尚无成功记录的编号：空编号/空承诺/非正数量 → ErrInvalidParam；
	// 合法参数引用未知承诺 → ErrNotFound；已关闭 → closed；超量 → exceeded。
	if _, err := s.Use("", "c3", 1, nowOK); !errors.Is(err, ErrInvalidParam) {
		t.Fatalf("empty usage id: %v", err)
	}
	if _, err := s.Use("x1", "", 1, nowOK); !errors.Is(err, ErrInvalidParam) {
		t.Fatalf("empty commit id: %v", err)
	}
	if _, err := s.Use("x2", "c3", 0, nowOK); !errors.Is(err, ErrInvalidParam) {
		t.Fatalf("zero qty: %v", err)
	}
	if _, err := s.Use("x3", "cNope", 1, nowOK); !errors.Is(err, ErrNotFound) {
		t.Fatalf("unknown commitment: %v", err)
	}
	if _, err := s.Use("x4", "c1", 1, nowOK); !errors.Is(err, ErrCommitmentClosed) {
		t.Fatalf("closed commitment: %v", err)
	}
	if _, err := s.Use("x5", "c2", 2, nowOK); !errors.Is(err, ErrCommitmentClosed) {
		t.Fatalf("canceled commitment: %v", err)
	}
	// c3 未使用数量为 1，超量。
	if _, err := s.Use("x6", "c3", 2, nowOK.Add(-2*day)); !errors.Is(err, ErrUsageExceeded) {
		t.Fatalf("exceed: %v", err)
	}
	// 失败不占用编号：修正内容后可成功。
	if _, err := s.Use("x6", "c3", 1, nowOK.Add(-2*day)); err != nil {
		t.Fatalf("reuse id after failure: %v", err)
	}
}

